-- CAREEROS P3-T05: Paystack provider (phase plan D1, D9). The CREATE TABLE, index, constraint and column statements are
-- generated by drizzle-kit; the row-level security, the definer functions and the grants are written by hand, following
-- P3-T04. Runs as the migration (owner) role. Down migration: down.sql in this folder.
--> statement-breakpoint
CREATE TABLE "billing_provider_plan" (
	"id" text PRIMARY KEY DEFAULT gen_random_uuid()::text,
	"provider" text NOT NULL,
	"plan_id" text NOT NULL,
	"billing_interval" text NOT NULL,
	"currency" text NOT NULL,
	"seats" integer NOT NULL,
	"amount" bigint NOT NULL,
	"provider_plan_code" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "billing_provider_plan_interval_check" CHECK ("billing_interval" in ('month', 'year')),
	CONSTRAINT "billing_provider_plan_seats_check" CHECK ("seats" > 0 and "amount" >= 0)
);
--> statement-breakpoint
ALTER TABLE "subscription" ADD COLUMN "pending_seats" integer;--> statement-breakpoint
ALTER TABLE "subscription" ADD COLUMN "pending_replaces_subscription_id" text;--> statement-breakpoint
CREATE UNIQUE INDEX "billing_provider_plan_key" ON "billing_provider_plan" ("provider","plan_id","billing_interval","currency","seats","amount");--> statement-breakpoint
CREATE UNIQUE INDEX "billing_provider_plan_code_key" ON "billing_provider_plan" ("provider","provider_plan_code");--> statement-breakpoint
ALTER TABLE "billing_provider_plan" ADD CONSTRAINT "billing_provider_plan_plan_id_plan_id_fkey" FOREIGN KEY ("plan_id") REFERENCES "plan"("id");--> statement-breakpoint
ALTER TABLE "subscription" ADD CONSTRAINT "subscription_pending_seats_check" CHECK ("pending_seats" is null or "pending_seats" > 0);--> statement-breakpoint
-- 1. billing_provider_plan: global and platform only, like billing_event. The app role has NO privilege and NO policy on
-- it; the definer functions below are the only way in. The REVOKE is repeated in infra/db/bootstrap-roles.sql because
-- that script's blanket GRANT would undo it.
ALTER TABLE "billing_provider_plan" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "billing_provider_plan" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
DROP POLICY IF EXISTS "owner_access" ON "billing_provider_plan";--> statement-breakpoint
CREATE POLICY "owner_access" ON "billing_provider_plan" TO CURRENT_USER USING (true) WITH CHECK (true);--> statement-breakpoint
DO $$ BEGIN
	IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'careeros_app') THEN
		REVOKE ALL ON TABLE public.billing_provider_plan FROM careeros_app;
	END IF;
END $$;--> statement-breakpoint
COMMENT ON COLUMN "subscription"."pending_seats" IS 'A seat change that starts with the next paid period (P3-T05). Cleared when the payment for that count arrives.';--> statement-breakpoint
-- 2. careeros_set_subscription: the T01 function with the two pending fields added to its allow-list. Nothing else changes.
CREATE OR REPLACE FUNCTION public.careeros_set_subscription(
	p_org_id text, p_fields jsonb, p_actor_user_id text, p_source text
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
	allowed text[] := ARRAY[
		'provider', 'provider_customer_id', 'provider_subscription_id', 'status', 'seats', 'billing_interval',
		'current_period_start', 'current_period_end', 'trial_ends_at', 'grace_ends_at', 'ai_overage_allowed',
		'pending_seats', 'pending_replaces_subscription_id'
	];
	unknown_keys text[];
	rec public.subscription;
BEGIN
	IF p_fields IS NULL OR jsonb_typeof(p_fields) <> 'object' THEN
		RAISE EXCEPTION 'careeros_set_subscription: fields must be a JSON object';
	END IF;
	IF p_source IS NULL OR btrim(p_source) = '' THEN
		RAISE EXCEPTION 'careeros_set_subscription: a source is required';
	END IF;
	SELECT array_agg(k ORDER BY k) INTO unknown_keys FROM jsonb_object_keys(p_fields) AS k WHERE k <> ALL (allowed);
	IF unknown_keys IS NOT NULL THEN
		RAISE EXCEPTION 'careeros_set_subscription: unknown fields %', array_to_string(unknown_keys, ', ');
	END IF;
	PERFORM 1 FROM public.subscription WHERE organization_id = p_org_id FOR UPDATE;
	IF NOT FOUND THEN
		RAISE EXCEPTION 'careeros_set_subscription: no subscription for the organization';
	END IF;
	IF p_fields = '{}'::jsonb THEN
		RETURN;
	END IF;
	rec := jsonb_populate_record(NULL::public.subscription, p_fields);
	UPDATE public.subscription s SET
		provider = CASE WHEN p_fields ? 'provider' THEN rec.provider ELSE s.provider END,
		provider_customer_id = CASE WHEN p_fields ? 'provider_customer_id' THEN rec.provider_customer_id ELSE s.provider_customer_id END,
		provider_subscription_id = CASE WHEN p_fields ? 'provider_subscription_id' THEN rec.provider_subscription_id ELSE s.provider_subscription_id END,
		status = CASE WHEN p_fields ? 'status' THEN rec.status ELSE s.status END,
		seats = CASE WHEN p_fields ? 'seats' THEN rec.seats ELSE s.seats END,
		billing_interval = CASE WHEN p_fields ? 'billing_interval' THEN rec.billing_interval ELSE s.billing_interval END,
		current_period_start = CASE WHEN p_fields ? 'current_period_start' THEN rec.current_period_start ELSE s.current_period_start END,
		current_period_end = CASE WHEN p_fields ? 'current_period_end' THEN rec.current_period_end ELSE s.current_period_end END,
		trial_ends_at = CASE WHEN p_fields ? 'trial_ends_at' THEN rec.trial_ends_at ELSE s.trial_ends_at END,
		grace_ends_at = CASE WHEN p_fields ? 'grace_ends_at' THEN rec.grace_ends_at ELSE s.grace_ends_at END,
		ai_overage_allowed = CASE WHEN p_fields ? 'ai_overage_allowed' THEN rec.ai_overage_allowed ELSE s.ai_overage_allowed END,
		pending_seats = CASE WHEN p_fields ? 'pending_seats' THEN rec.pending_seats ELSE s.pending_seats END,
		pending_replaces_subscription_id = CASE WHEN p_fields ? 'pending_replaces_subscription_id' THEN rec.pending_replaces_subscription_id ELSE s.pending_replaces_subscription_id END,
		updated_at = now()
	WHERE s.organization_id = p_org_id;
	INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_type, target_id, metadata)
	VALUES (p_org_id, p_actor_user_id, 'subscription.updated', 'subscription', p_org_id,
		jsonb_build_object('source', p_source, 'fields', p_fields));
END
$$;--> statement-breakpoint
-- 3. careeros_billing_provider_plan_get: the provider plan code cached for one key, or null. Returns the code only.
CREATE OR REPLACE FUNCTION public.careeros_billing_provider_plan_get(
	p_provider text, p_plan_id text, p_interval text, p_currency text, p_seats integer, p_amount bigint
) RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
	SELECT provider_plan_code FROM public.billing_provider_plan
	WHERE provider = p_provider AND plan_id = p_plan_id AND billing_interval = p_interval AND currency = p_currency
		AND seats = p_seats AND amount = p_amount
$$;--> statement-breakpoint
-- 4. careeros_billing_provider_plan_put: caches a provider plan code. A key that is already cached keeps the code it has
-- (two servers creating the same plan at once agree on one) and that code is returned.
CREATE OR REPLACE FUNCTION public.careeros_billing_provider_plan_put(
	p_provider text, p_plan_id text, p_interval text, p_currency text, p_seats integer, p_amount bigint, p_code text
) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
	stored text;
BEGIN
	IF p_provider IS NULL OR p_provider !~ '^[a-z][a-z0-9_]{1,31}$' THEN
		RAISE EXCEPTION 'careeros_billing_provider_plan_put: invalid provider';
	END IF;
	IF p_code IS NULL OR p_code !~ '^[A-Za-z0-9_.:-]{1,128}$' THEN
		RAISE EXCEPTION 'careeros_billing_provider_plan_put: invalid plan code';
	END IF;
	INSERT INTO public.billing_provider_plan (provider, plan_id, billing_interval, currency, seats, amount, provider_plan_code)
	VALUES (p_provider, p_plan_id, p_interval, p_currency, p_seats, p_amount, p_code)
	ON CONFLICT DO NOTHING;
	SELECT provider_plan_code INTO stored FROM public.billing_provider_plan
	WHERE provider = p_provider AND plan_id = p_plan_id AND billing_interval = p_interval AND currency = p_currency
		AND seats = p_seats AND amount = p_amount;
	RETURN stored;
END
$$;--> statement-breakpoint
-- 5. careeros_billing_provider_plan_by_code: what a provider plan code stands for (a signed webhook names it).
CREATE OR REPLACE FUNCTION public.careeros_billing_provider_plan_by_code(p_provider text, p_code text)
RETURNS TABLE (plan_id text, billing_interval text, currency text, seats integer, amount bigint)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
	SELECT plan_id, billing_interval, currency, seats, amount FROM public.billing_provider_plan
	WHERE provider = p_provider AND provider_plan_code = p_code
$$;--> statement-breakpoint
-- 6. careeros_billing_org_by_provider_ref: the one organization a provider's subscription or customer code belongs to,
-- or null. The webhook has no organization context and row-level security hides every subscription from it, so this
-- answers with an organization id and nothing else. Only called with a code from a signature-verified event. A
-- subscription code is unique; a customer code can be shared (one person paying for two organizations), and then it
-- names no organization (null), never a guess.
CREATE OR REPLACE FUNCTION public.careeros_billing_org_by_provider_ref(
	p_provider text, p_subscription_code text, p_customer_code text
) RETURNS text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
	found text[];
BEGIN
	IF p_subscription_code IS NOT NULL THEN
		SELECT array_agg(organization_id) INTO found FROM public.subscription
		WHERE provider = p_provider AND (provider_subscription_id = p_subscription_code
			OR pending_replaces_subscription_id = p_subscription_code);
		IF found IS NOT NULL AND array_length(found, 1) = 1 THEN
			RETURN found[1];
		END IF;
	END IF;
	IF p_customer_code IS NOT NULL THEN
		SELECT array_agg(organization_id) INTO found FROM public.subscription
		WHERE provider = p_provider AND provider_customer_id = p_customer_code;
		IF found IS NOT NULL AND array_length(found, 1) = 1 THEN
			RETURN found[1];
		END IF;
	END IF;
	RETURN NULL;
END
$$;--> statement-breakpoint
-- 7. careeros_billing_reminder_orgs: ids of organizations paying one period at a time through the provider (an active
-- subscription with the provider and no provider subscription, so M-Pesa) whose paid period ends within three days.
-- The reminder job re-reads each one inside its scope before it sends anything.
CREATE OR REPLACE FUNCTION public.careeros_billing_reminder_orgs(p_provider text, p_now timestamptz)
RETURNS TABLE (organization_id text)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
	SELECT o.id FROM public.organization o JOIN public.subscription s ON s.organization_id = o.id
	WHERE o.status = 'active' AND s.provider = p_provider AND s.status = 'active' AND s.provider_subscription_id IS NULL
		AND s.current_period_end IS NOT NULL AND s.current_period_end > p_now
		AND s.current_period_end <= p_now + interval '3 days'
	ORDER BY o.id LIMIT 500
$$;--> statement-breakpoint
-- 8. careeros_billing_due_orgs: the T04 function plus one more case. A plan paid one period at a time (provider paystack
-- with no provider subscription: M-Pesa) gets no provider event when its paid period ends unpaid, so the job must look
-- at it. The job re-reads each organization under its lock and decides with the state machine.
CREATE OR REPLACE FUNCTION public.careeros_billing_due_orgs(p_now timestamptz) RETURNS TABLE (organization_id text)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
	SELECT o.id FROM public.organization o JOIN public.subscription s ON s.organization_id = o.id
	WHERE o.status <> 'suspended' AND (
		(o.status = 'trial' AND s.trial_ends_at <= p_now)
		OR (o.status = 'past_due' AND s.grace_ends_at <= p_now)
		OR (s.status = 'canceled' AND coalesce(s.current_period_end, p_now) <= p_now)
		OR (o.status = 'active' AND s.status = 'active' AND s.provider = 'paystack' AND s.provider_subscription_id IS NULL
			AND s.current_period_end IS NOT NULL AND s.current_period_end <= p_now)
	)
	ORDER BY o.id LIMIT 500
$$;--> statement-breakpoint
DO $$ BEGIN
	REVOKE ALL ON FUNCTION public.careeros_set_subscription(text, jsonb, text, text) FROM PUBLIC;
	REVOKE ALL ON FUNCTION public.careeros_billing_provider_plan_get(text, text, text, text, integer, bigint) FROM PUBLIC;
	REVOKE ALL ON FUNCTION public.careeros_billing_provider_plan_put(text, text, text, text, integer, bigint, text) FROM PUBLIC;
	REVOKE ALL ON FUNCTION public.careeros_billing_provider_plan_by_code(text, text) FROM PUBLIC;
	REVOKE ALL ON FUNCTION public.careeros_billing_org_by_provider_ref(text, text, text) FROM PUBLIC;
	REVOKE ALL ON FUNCTION public.careeros_billing_reminder_orgs(text, timestamptz) FROM PUBLIC;
	IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'careeros_app') THEN
		GRANT EXECUTE ON FUNCTION public.careeros_set_subscription(text, jsonb, text, text) TO careeros_app;
		GRANT EXECUTE ON FUNCTION public.careeros_billing_provider_plan_get(text, text, text, text, integer, bigint) TO careeros_app;
		GRANT EXECUTE ON FUNCTION public.careeros_billing_provider_plan_put(text, text, text, text, integer, bigint, text) TO careeros_app;
		GRANT EXECUTE ON FUNCTION public.careeros_billing_provider_plan_by_code(text, text) TO careeros_app;
		GRANT EXECUTE ON FUNCTION public.careeros_billing_org_by_provider_ref(text, text, text) TO careeros_app;
		GRANT EXECUTE ON FUNCTION public.careeros_billing_reminder_orgs(text, timestamptz) TO careeros_app;
	END IF;
END $$;
